    const TOOL_IS_STANDALONE_STATION_OVERVIEW =
        TOOL_IS_TOP_WINDOW &&
        TOOL_IS_STATION_OVERVIEW_ROUTE;

    const TOOL_IS_STATION_OVERVIEW_FRAME = (() => {
        if (
            TOOL_IS_TOP_WINDOW ||
            !TOOL_IS_STATION_OVERVIEW_ROUTE
        ) return false;
        try {
            if (window.top.location.origin !== location.origin) return false;
        } catch (_error) {
            return false;
        }

        return true;
    })();

